<?php declare(strict_types=1); namespace Codejitsu\Ai\Commands;
use Codejitsu\Ai\Console\AiTui; use Codejitsu\Ai\Console\TerminalConversationIO; use Codejitsu\Ai\Tools\AllowNamedTools; use Codejitsu\Ai\Vessels\VesselRunnerFactory; use Codejitsu\ExecutionContext; use RuntimeException;
final class Ai { public static function run(ExecutionContext $c):string{$args=is_array($c->arguments)?array_values($c->arguments):[];$v=array_shift($args);if(!is_string($v)||trim($v)==='')throw new RuntimeException('A Vessel name or URI is required.');$approved=[];$prompt=[];foreach($args as $a){if(is_string($a)&&str_starts_with($a,'--approve-tool=')){$approved[]=substr($a,15);}elseif(is_string($a))$prompt[]=$a;}if($prompt===[])throw new RuntimeException('A prompt is required.');$codex=$c->codex??throw new RuntimeException('AI commands require a bound Codex.');$s=(new VesselRunnerFactory())->make($codex)->start(trim($v),approval:new AllowNamedTools($approved));return $s->send(implode(' ',$prompt))->text."\n";} public static function tui(ExecutionContext $c):int{$codex=$c->codex??throw new RuntimeException('AI commands require a bound Codex.');return(new AiTui((new VesselRunnerFactory())->make($codex),$codex))->run(new TerminalConversationIO());} }
